// Example: a component with typed props
interface ButtonProps {
  label: string;
  onClick: () => void;
}

function Button({ label, onClick }: ButtonProps) {
  return <button onClick={onClick}>{label}</button>;
}

// Example: adding a polymorphic 'as' prop
interface ButtonProps {
  as?: 'button' | 'a';
  children: React.ReactNode;
}

const Button = ({ as = 'button', children }: ButtonProps) => {
  const Component = as;
  return <Component>{children}</Component>;
};

